   for dy in (-1,0,1):
    v=(x+dx,y+dy)
    if (dx or dy) and v in S:
     # penalize diagonal shortcuts where an orthogonal alternative exists
     c=math.hypot(dx,dy)
     if dx and dy and ((x+dx,y) in S or (x,y+dy) in S): c=1.5
     nd=d+c
     if nd<dist.get(v,1e9):dist[v]=nd;prev[v]=u;heapq.heappush(h,(nd,v))
