   if np.linalg.norm(np.array(v)-last)>=step:out.append(v);last=np.array(v,float)
  if out[-1]!=p[-1]:out.append(p[-1])
  return out
 print(start,'->',goal,'snapped',s,g,'len',len(p),'samples',samp(p))
 return p
